import{_ as s,c as t,o as i,b0 as e}from"./chunks/framework.BWMBvyU7.js";const n="/programming-docs/assets/image-20221018174753735.WDAjQHiy.png",m=JSON.parse('{"title":"LV200-man命令简介","description":null,"frontmatter":{"title":"LV200-man命令简介","date":"2026-03-11T15:54:01.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/os/linux-basic/126d38a642c9005502b6d106","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-11T15:54:01.005Z","fulluuid":"502b6d1065e04c23a79fb3d601ea8d55","useduuid":"502b6d106"}},"headers":[],"relativePath":"sdoc/os/linux-basic/126d38a642c9005502b6d106.md","filePath":"sdoc/03-操作系统/01-Linux基础/LV200-man命令简介.md","lastUpdated":1773672539000}'),l={name:"sdoc/os/linux-basic/126d38a642c9005502b6d106.md"};function d(r,a,p,h,o,c){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="lv200-man命令简介" tabindex="-1">LV200-man命令简介 <a class="header-anchor" href="#lv200-man命令简介" aria-label="Permalink to &quot;LV200-man命令简介&quot;">​</a></h1><h2 id="一、man-命令" tabindex="-1">一、man 命令 <a class="header-anchor" href="#一、man-命令" aria-label="Permalink to &quot;一、man 命令&quot;">​</a></h2><p>man 是 manual 的简称，中文称之为手册。man 手册是 linux 系统提供的一种帮助手册，通过这个命令我们可以得到一些帮助信息， 其内容包括命令语法、各选项的意义及相关命令 。更为强大的是，不仅可以查看 Linux 中命令的使用帮助，还可以查看软件服务配置文件、系统调用、库函数等帮助信息。man 手册页文件存放在/usr/share/man 目录下。</p><h3 id="_1-man-手册安装" tabindex="-1">1. man 手册安装 <a class="header-anchor" href="#_1-man-手册安装" aria-label="Permalink to &quot;1. man 手册安装&quot;">​</a></h3><p>通常来说，系统只会默认安装第 1 册的 man 手册，也就是查找 shell 命令的 man 手册，若是发现自己的 man 手册有缺失，我们可以通过以下命令安装：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manpages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manpages-dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manpages-posix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manpages-posix-dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_2-man-命令" tabindex="-1">2. man 命令 <a class="header-anchor" href="#_2-man-命令" aria-label="Permalink to &quot;2. man 命令&quot;">​</a></h3><h4 id="_2-1-使用格式" tabindex="-1">2.1 使用格式 <a class="header-anchor" href="#_2-1-使用格式" aria-label="Permalink to &quot;2.1 使用格式&quot;">​</a></h4><p>使用 man 命令可以找到特定的联机帮助页，并提供简短的命令说明。联机帮助页提供了指定命令 command_name 的相关信息，包括：名称、函数、语法以及可选参数描述等。无论帮助有多长，都遵循这个格式显示。在页面很多的情况下使用 PageUp 和 PageDown 键翻页。最后，使用 ：q 退出帮助页面。一般使用格式为:</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [option] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>参数说明</strong>】</p><ul><li>option ：man 命令的一些选项，是可选的。常见 option 选项如下：</li></ul><table><tbody><tr><td align="center"> option </td> <td align="center"> 说明 </td></tr><tr><td align="center">-a </td> <td align="left"> 在所有的 man 帮助手册中搜索 </td></tr><tr><td align="center">-f </td> <td align="left"> 显示给定关键字的简短描述信息 </td></tr><tr><td align="center">-p </td> <td align="left"> 指定内容时使用分页程序 </td></tr><tr><td align="center">-M </td> <td align="left"> 指定 man 手册搜索的路径 </td></tr><tr><td align="center">-w </td> <td align="left"> 显示文件所在位置 </td></tr></tbody></table> - name ：要查询的命令名称或者要查询的函数名等。 <h4 id="_2-2-使用实例" tabindex="-1">2.2 使用实例 <a class="header-anchor" href="#_2-2-使用实例" aria-label="Permalink to &quot;2.2 使用实例&quot;">​</a></h4><h5 id="_2-2-1-查询命令的帮助文档" tabindex="-1">2.2.1 查询命令的帮助文档 <a class="header-anchor" href="#_2-2-1-查询命令的帮助文档" aria-label="Permalink to &quot;2.2.1 查询命令的帮助文档&quot;">​</a></h5><p>我们在终端执行以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后我们就会进入 man 手册，我们会得到以下信息：</p><img src="`+n+`" alt="image-20221018174753735" style="zoom:50%;"><h5 id="_2-2-2-查询有哪些页有帮助信息" tabindex="-1">2.2.2 查询有哪些页有帮助信息 <a class="header-anchor" href="#_2-2-2-查询有哪些页有帮助信息" aria-label="Permalink to &quot;2.2.2 查询有哪些页有帮助信息&quot;">​</a></h5><p>我们在终端执行以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后我们回的到以下信息：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hk@vm:~$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> man</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (2)             - read from a file descriptor</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-帮助信息的分类" tabindex="-1">3. 帮助信息的分类 <a class="header-anchor" href="#_3-帮助信息的分类" aria-label="Permalink to &quot;3. 帮助信息的分类&quot;">​</a></h3><p>我们在终端执行以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> man</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>我们会得到 man 命令的班助手册，man 命令帮助我们查找需要的信息，这些信息可以分为以下几类：</p><table tabindex="0"><thead><tr><th style="text-align:center;">编号</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td>可执行程序或 shell 命令</td></tr><tr><td style="text-align:center;">2</td><td>系统调用(内核提供的函数)</td></tr><tr><td style="text-align:center;">3</td><td>库调用(程序库中的函数)</td></tr><tr><td style="text-align:center;">4</td><td>特殊文件(通常位于 /dev)</td></tr><tr><td style="text-align:center;">5</td><td>文件格式和规范，如 /etc/passwd</td></tr><tr><td style="text-align:center;">6</td><td>游戏</td></tr><tr><td style="text-align:center;">7</td><td>杂项(包括宏包和规范，如 man(7)，groff(7))</td></tr><tr><td style="text-align:center;">8</td><td>系统管理命令(通常只针对 root 用户)</td></tr><tr><td style="text-align:center;">9</td><td>内核例程（非标准）</td></tr></tbody></table><p>可以看到其实 man 手册一共有 9 个章节，这 9 个章节帮助文档分别管理不同的帮助信息。我们可以使用前边的编号来直接查询相应册中的帮助信息，比如：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 将会得到 read 命令的帮助手册</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 将会得到 read() 函数的帮助手册</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>默认将按预定的顺序查找所有可用的章节 (默认是“ 1 n l 8 3 2 3posix 3pm 3perl 5 4 9 6 7 ”，除非被 /etc/manpath.config 中的 SECTION 指令覆盖)，并只显示找到的第一个 页，即使多个章节中都有这个 页面。额，写笔记的时候忘记在哪看到的了，现在也看不太懂，不过我们知道 man 是按预定顺序来查找的就行，这不是重点。</p><h3 id="_4-具体帮助页" tabindex="-1">4. 具体帮助页 <a class="header-anchor" href="#_4-具体帮助页" aria-label="Permalink to &quot;4. 具体帮助页&quot;">​</a></h3><p>一个手册页面包含若干个小节。小节名称通常包括 NAME，概述(SYNOPSIS)，配置(CONFIGURATION)，描述(DESCRIPTION)，选项(OPTIONS)，退出状态(EXIT STATUS)，返回值(RETURN VALUE)，错误(ERRORS)，环境(ENVIRONMENT)，文件(FILES)，版本(VERSIONS)，符合标准(CONFORMING TO)，注(NOTES)，缺陷(BUGS)，示例(EXAMPLE)，作者(AUTHORS)，和 亦见(SEE ALSO)。常见的几个如下：</p><table tabindex="0"><thead><tr><th>名称</th><th>含义</th></tr></thead><tbody><tr><td>NAME</td><td>命令的名称</td></tr><tr><td>SYNOPSIS</td><td>命令的语法格式</td></tr><tr><td>DESCRIPTION</td><td>命令的一般描述以及用途</td></tr><tr><td>OPTIONS</td><td>描述命令所有的参数或选项</td></tr><tr><td>SEE ALSO</td><td>列出联机帮助页中与该命令直接相关或功 能相近的其他命令</td></tr><tr><td>BUGS</td><td>解释命令或其输出中存在的任何已知的问题或缺陷</td></tr><tr><td>EXAMPLES</td><td>普通的用法示例</td></tr><tr><td>AUTHORS</td><td>联机帮助页以及命令的作者</td></tr></tbody></table>`,36)])])}const g=s(l,[["render",d]]);export{m as __pageData,g as default};
